def is_ip_allowed(client_ip):
    wl = load_ip_whitelist()
    if wl.get('mode') != 'whitelist':
        return True
    if client_ip in ('127.0.0.1', '::1', 'localhost'):
        return True
    return client_ip in wl.get('whitelist', [])

